def read(name):return json.loads((ROOT/'results'/name).read_text())
def picture(name):return 'data:image/png;base64,'+base64.b64encode((ROOT/'results'/name).read_bytes()).decode()

data={'bench':read('benchmark.json'),'train':read('training.json'),'trainBench':read('training_benchmark.json'),
      'validation':read('validation.json'),'extra':read('additional_validation.json'),'quality':read('quality.json'),
      'gradient':read('gradient_validation.json'),'trainGraphCheck':read('train_graph_validation.json'),
      'graphTrain':read('graph_training/training.json')}
for row in data['bench']['rows']:
    row['pairedSpeedups']=[b/v for b,v in zip(data['bench']['rows'][0]['samples_ms'],row['samples_ms'])]
data['images']={}
for name in ['graph_fp32','graph_amp','ddim50_amp','ddim20_amp']:
    data['images'][name]={'samples':picture(name+'_25.png'),'trajectory':picture(name+'_trajectory.png'),'first':picture(name+'.png')}
data['epoch5']=picture('epoch5.png');data['equivalence']=picture('equivalence.png')

